public static Map<String, List<Polygon>> readOneToManyPolygons(InputStream stream) throws IOException {
  HashMap<String, List<Polygon>> mapping = new HashMap<String, List<Polygon>>();
  LineNumberReader reader = null;
  try {
    reader = new LineNumberReader(new InputStreamReader(stream));
    String current = reader.readLine();
    while (current != null) {
      if (current.trim().length() != 0) {
        try {
          readMultiplePolygons(current, mapping);
        } catch (IndexOutOfBoundsException | UnsupportedOperationException | ClassCastException | NullPointerException | IllegalArgumentException | IllegalStateException e) {
          e.printStackTrace();
          System.exit(0);
        }
      }
      current = reader.readLine();
    }
  } catch (IOException ioe) {
    ioe.printStackTrace();
    System.exit(0);
  } finally {
    try {
      if (reader != null) reader.close();
    } catch (IOException e) {
    }
  }
  return mapping;
}
